import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

void main() => runApp(MyApp());

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(home: IconAnimator());
  }
}

class IconAnimator extends StatefulWidget {
  @override
  _IconAnimatorState createState() => _IconAnimatorState();
}

class _IconAnimatorState extends State<IconAnimator>
    with SingleTickerProviderStateMixin {
  bool _isRotated = false;
  late AnimationController _controller;
  late Animation<double> _animation;

 final Uint8List iconBytes = base64Decode(
  ''
);
  @override
  void initState() {
    super.initState();
    _controller =
        AnimationController(vsync: this, duration: Duration(milliseconds: 400));
    _animation = Tween<double>(begin: 0.0, end: 0.5).animate(
        CurvedAnimation(parent: _controller, curve: Curves.easeInOut));
  }

  void _toggleRotation() {
    setState(() {
      _isRotated = !_isRotated;
      _isRotated ? _controller.forward() : _controller.reverse();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.grey.shade100,
      body: Center(
        child: GestureDetector(
          onTap: _toggleRotation,
          child: RotationTransition(
            turns: _animation,
            child: Image.memory(iconBytes, width: 64),
          ),
        ),
      ),
    );
  }
}
